import { chromium } from '@playwright/test'
import { writeFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'

const EXE = 'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'
const REF = 'file:///C:/Users/Administrator/Downloads/%E6%95%B0%E6%99%BA%E5%88%86%E6%9E%90.html'
const OUT = 'artifacts/shuzhi-ref'
mkdirSync(OUT, { recursive: true })

const browser = await chromium.launch({ headless: true, executablePath: EXE })
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 })
await page.goto(REF, { waitUntil: 'load' })
await page.evaluate(async () => { await document.fonts.ready })
await page.waitForTimeout(1200)

const bundle = await page.evaluate(() => {
  const cssParts = []
  for (const sheet of document.styleSheets) {
    if (sheet.href) continue // cross-origin Google Fonts CSS, kept as <link>
    let text = ''
    try {
      for (const rule of sheet.cssRules) text += rule.cssText + '\n'
    } catch { /* ignore */ }
    cssParts.push({ owner: sheet.ownerNode?.tagName, rules: sheet.cssRules.length, text })
  }
  const main = document.querySelector('main')
  const sections = [...document.querySelectorAll('main section')].map((s, i) => {
    const r = s.getBoundingClientRect()
    return { index: i, y: Math.round(r.y), h: Math.round(r.height), cls: s.className }
  })
  return {
    cssParts,
    mainHtml: main ? main.outerHTML : '',
    bodyHtml: document.body.outerHTML,
    sections,
    mainBox: main ? { w: main.getBoundingClientRect().width, h: main.getBoundingClientRect().height } : null,
    bodyScrollHeight: document.body.scrollHeight,
  }
})

const tailwind = bundle.cssParts.map(p => `/* owner=${p.owner} rules=${p.rules} */\n${p.text}`).join('\n')
writeFileSync(join(OUT, 'tailwind.css'), tailwind, 'utf8')
writeFileSync(join(OUT, 'main.html'), bundle.mainHtml, 'utf8')
writeFileSync(join(OUT, 'body.html'), bundle.bodyHtml, 'utf8')
writeFileSync(join(OUT, 'spec.json'), JSON.stringify({ sections: bundle.sections, mainBox: bundle.mainBox, bodyScrollHeight: bundle.bodyScrollHeight, cssRules: bundle.cssParts.map(p => ({ owner: p.owner, rules: p.rules })) }, null, 2), 'utf8')

await page.screenshot({ path: join(OUT, 'baseline-full.png'), fullPage: true, animations: 'disabled' })
await page.locator('main').screenshot({ path: join(OUT, 'baseline-main.png'), animations: 'disabled' })
console.log(JSON.stringify({ sections: bundle.sections, mainBox: bundle.mainBox, bodyScrollHeight: bundle.bodyScrollHeight, cssRules: bundle.cssParts.map(p => ({ owner: p.owner, rules: p.rules })), tailwindBytes: Buffer.byteLength(tailwind), mainHtmlBytes: Buffer.byteLength(bundle.mainHtml) }, null, 2))
await browser.close()

