import { chromium } from '@playwright/test'
import { writeFileSync, mkdirSync } from 'node:fs'

const EXE = 'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'
const REF = 'file:///C:/Users/Administrator/Downloads/%E6%95%B0%E6%99%BA%E5%88%86%E6%9E%90.html'
const MINE = 'http://127.0.0.1:8095/#/pages/data/index'
const OUT = 'artifacts/shuzhi-ref'
mkdirSync(OUT, { recursive: true })

const HIDE = `header, nav, .app-header, .bottom-nav, .uni-tabbar, uni-tabbar,
[class*="bottom-nav"], [class*="app-header"], .uni-page-head, uni-page-head,
.uni-page-wrapper > uni-page-head { display: none !important }`

const browser = await chromium.launch({ headless: true, executablePath: EXE })
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 })

const ref = await ctx.newPage()
await ref.goto(REF, { waitUntil: 'load' })
await ref.waitForTimeout(1800)
await ref.evaluate(async () => { await document.fonts.ready })
await ref.addStyleTag({ content: HIDE })
await ref.waitForTimeout(400)

const mine = await ctx.newPage()
const errs = []
mine.on('pageerror', e => errs.push(String(e)))
await mine.goto(MINE, { waitUntil: 'load' })
await mine.waitForSelector('main.shuzhi-main', { timeout: 30_000 })
await mine.evaluate(async () => { await document.fonts.ready })
await mine.addStyleTag({ content: HIDE })
await mine.waitForTimeout(400)

const info = await mine.evaluate(() => {
  const main = document.querySelector('main.shuzhi-main')
  const r = main?.getBoundingClientRect()
  const h2 = document.querySelector('main.shuzhi-main h2')
  const icon = document.querySelector('main.shuzhi-main .material-symbols-outlined')
  const body = getComputedStyle(main)
  return {
    mainBox: r ? { w: r.width, h: r.height, x: r.x, y: r.y } : null,
    sections: document.querySelectorAll('main.shuzhi-main section').length,
    mainFont: body.fontFamily,
    mainFontSize: body.fontSize,
    mainColor: body.color,
    h2Text: h2?.textContent,
    h2Font: h2 ? getComputedStyle(h2).fontSize : null,
    iconFont: icon ? getComputedStyle(icon).fontFamily : null,
    iconText: icon?.textContent,
    plusLoaded: document.fonts.check('12px "Plus Jakarta Sans"'),
    injectedStyles: document.querySelectorAll('[data-shuzhi-ref]').length,
    htmlFontSize: getComputedStyle(document.documentElement).fontSize,
    pageFontSize: (() => { const p = document.querySelector('page'); return p ? getComputedStyle(p).fontSize : null })(),
  }
})

const refBuf = await ref.locator('main').screenshot({ animations: 'disabled' })
const mineBuf = await mine.locator('main.shuzhi-main').screenshot({ animations: 'disabled' })
writeFileSync(`${OUT}/ref-main.png`, refBuf)
writeFileSync(`${OUT}/mine-main.png`, mineBuf)

const cmp = await mine.evaluate(
  ({ a, b, delta }) => {
    const load = src => new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = src })
    return Promise.all([load(a), load(b)]).then(([A, B]) => {
      const w = Math.min(A.width, B.width), h = Math.min(A.height, B.height)
      const c = document.createElement('canvas'); c.width = w; c.height = h
      const cx = c.getContext('2d')
      const read = img => { const t = document.createElement('canvas'); t.width = w; t.height = h; t.getContext('2d').drawImage(img, 0, 0, w, h, 0, 0, w, h); return t.getContext('2d').getImageData(0, 0, w, h).data }
      const x = read(A), y = read(B)
      let changed = 0
      for (let i = 0; i < x.length; i += 4) {
        const d = Math.abs(x[i] - y[i]) + Math.abs(x[i + 1] - y[i + 1]) + Math.abs(x[i + 2] - y[i + 2])
        if (d > delta) changed++
      }
      return { w, h, refSize: [A.width, A.height], mineSize: [B.width, B.height], changed, total: w * h, ratio: changed / (w * h) }
    })
  },
  { a: `data:image/png;base64,${refBuf.toString('base64')}`, b: `data:image/png;base64,${mineBuf.toString('base64')}`, delta: 24 },
)

console.log(JSON.stringify({ info, errs, cmp, ratioPct: +(cmp.ratio * 100).toFixed(4) }, null, 2))
await browser.close()

