import { chromium } from '@playwright/test'
import { readFileSync, writeFileSync } from 'node:fs'

const EXE = 'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'
const A = readFileSync('artifacts/shuzhi-ref/ref-main.png').toString('base64')
const B = readFileSync('artifacts/shuzhi-ref/mine-main.png').toString('base64')
const browser = await chromium.launch({ headless: true, executablePath: EXE })
const page = await browser.newPage()
const res = await page.evaluate(
  ({ a, b }) => {
    const load = src => new Promise((res, rej) => { const i = new Image(); i.onload = () => res(i); i.onerror = rej; i.src = src })
    return Promise.all([load(a), load(b)]).then(([A, B]) => {
      const w = Math.min(A.width, B.width), h = Math.min(A.height, B.height)
      const cv = document.createElement('canvas'); cv.width = w; cv.height = h
      const cx = cv.getContext('2d')
      const read = img => { const t = document.createElement('canvas'); t.width = w; t.height = h; t.getContext('2d').drawImage(img, 0, 0, w, h, 0, 0, w, h); return t.getContext('2d').getImageData(0, 0, w, h).data }
      const x = read(A), y = read(B)
      const out = cv.getContext('2d').createImageData(w, h)
      const yBuckets = {}, xBuckets = {}
      let minX = w, maxX = 0, minY = h, maxY = 0, changed = 0
      const samples = []
      for (let p = 0; p < w * h; p++) {
        const i = p * 4
        const d = Math.abs(x[i] - y[i]) + Math.abs(x[i + 1] - y[i + 1]) + Math.abs(x[i + 2] - y[i + 2])
        const px = p % w, py = (p / w) | 0
        if (d > 24) {
          changed++
          out.data[i] = 255; out.data[i + 1] = 0; out.data[i + 2] = 0; out.data[i + 3] = 255
          minX = Math.min(minX, px); maxX = Math.max(maxX, px); minY = Math.min(minY, py); maxY = Math.max(maxY, py)
          const by = Math.floor(py / 100) * 100
          const bx = Math.floor(px / 50) * 50
          yBuckets[by] = (yBuckets[by] || 0) + 1
          xBuckets[bx] = (xBuckets[bx] || 0) + 1
          if (samples.length < 12) samples.push({ x: px, y: py, d, ref: [x[i], x[i + 1], x[i + 2]], mine: [y[i], y[i + 1], y[i + 2]] })
        } else {
          out.data[i] = x[i]; out.data[i + 1] = x[i + 1]; out.data[i + 2] = x[i + 2]; out.data[i + 3] = 255
        }
      }
      cv.getContext('2d').putImageData(out, 0, 0)
      return { changed, bbox: { minX, maxX, minY, maxY }, yBuckets, xBuckets, samples, diffPng: cv.toDataURL('image/png').split(',')[1] }
    })
  },
  { a: `data:image/png;base64,${A}`, b: `data:image/png;base64,${B}` },
)
writeFileSync('artifacts/shuzhi-ref/diff-map.png', Buffer.from(res.diffPng, 'base64'))
delete res.diffPng
console.log(JSON.stringify(res, null, 2))
await browser.close()

